// Meteor Dodge game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 600;

// Ship
const ship = {
  width: 40,
  height: 20,
  x: canvas.width / 2 - 20,
  y: canvas.height - 30,
  speed: 5,
  color: 'cyan'
};

let leftPressed = false;
let rightPressed = false;
let meteors = [];
let score = 0;
let gameOver = false;
let frameCount = 0;

function drawShip() {
  ctx.fillStyle = ship.color;
  ctx.fillRect(ship.x, ship.y, ship.width, ship.height);
}

function spawnMeteor() {
  const size = 20 + Math.random() * 20;
  meteors.push({
    x: Math.random() * (canvas.width - size),
    y: -size,
    size,
    speed: 2 + Math.random() * 2 + frameCount * 0.001
  });
}

function drawMeteors() {
  ctx.fillStyle = 'orange';
  meteors.forEach(m => {
    ctx.beginPath();
    ctx.arc(m.x + m.size / 2, m.y + m.size / 2, m.size / 2, 0, Math.PI * 2);
    ctx.fill();
  });
}

function updateMeteors() {
  meteors.forEach((m, i) => {
    m.y += m.speed;
    // Remove meteors that passed bottom and increment score
    if (m.y - m.size > canvas.height) {
      meteors.splice(i, 1);
      score++;
    }
    // Collision with ship
    if (
      m.x < ship.x + ship.width &&
      m.x + m.size > ship.x &&
      m.y < ship.y + ship.height &&
      m.y + m.size > ship.y
    ) {
      gameOver = true;
    }
  });
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function clear() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
}

function gameLoop() {
  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '30px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
    ctx.fillText(`Score: ${score}`, canvas.width / 2 - 60, canvas.height / 2 + 40);
    return;
  }
  clear();
  // handle input
  if (leftPressed && ship.x > 0) ship.x -= ship.speed;
  if (rightPressed && ship.x + ship.width < canvas.width) ship.x += ship.speed;

  if (frameCount % 60 === 0) spawnMeteor(); // roughly 1 per second

  updateMeteors();
  drawMeteors();
  drawShip();
  drawScore();
  frameCount++;
  requestAnimationFrame(gameLoop);
}

// Input listeners
window.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') leftPressed = true;
  if (e.key === 'ArrowRight') rightPressed = true;
});
window.addEventListener('keyup', e => {
  if (e.key === 'ArrowLeft') leftPressed = false;
  if (e.key === 'ArrowRight') rightPressed = false;
});

gameLoop();
